function applyMasterTtsData(){
  try{
    if(typeof DB==='undefined'||!DB) return;
    Object.keys(MASTER_TTS).forEach(key=>{
      const arr=DB[key], patch=MASTER_TTS[key];
      if(!Array.isArray(arr)||!Array.isArray(patch)) return;
      const byNo=new Map(patch.map(x=>[Number(x.no),x]));
      arr.forEach(q=>{
        const t=byNo.get(Number(q.no));
        if(!t) return;
        q.ttsQ=t.ttsQ;
        q.ttsOpts=t.ttsOpts.slice();
      });
    });
  }catch(e){}
}
applyMasterTtsData();
